import { EP } from "../_client";
import { Routes } from "@angular/router";
import { Type } from "@angular/core";
import { MenuIndexComponent } from "@_core/_route/menu-index/menu-index.component";


export class RoutezFeatureModule {
  private routes: Routes = [];
  constructor(
    private layer: string[],
    private routeModule: string,
  ) {
    this.addIndexRoute();
  }
  private addIndexRoute() {
    this.routes.push(
      {
        path: '',
        redirectTo: 'index',
        pathMatch: 'full',
      },
      {
        path: 'index',
        component: MenuIndexComponent,
        data: {
          title: this.layer[this.layer.length - 1],
          linkPaginate: ``,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Add, EP.GetsPaginate],
          layer: this.layer,
        },
      }
    );
  }
  feature(
    listComponent: Type<any>,
    addComponent: Type<any>,
    path: string,
    title: string,
  ): this {

    this.routes.push(
      {
        path,
        component: listComponent,
        data: {
          title,
          linkPaginate: ``,
          linkAdd: `/${this.routeModule}/${path}-add`,
          linkUpdate: `/${this.routeModule}/${path}-edit/`,
          permission: [EP.GetsPaginate, EP.Add, EP.Update, EP.Delete],
          layer: [...this.layer, '| List'],
        },
      },

      {
        path: `${path}-add`,
        component: addComponent,
        data: {
          title,
          linkPaginate: `/${this.routeModule}/${path}`,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Get, EP.Add ],
          layer: [...this.layer, '| Add'],
        },
      },
      {
        path: `${path}-edit/:id`,
        component: addComponent,
        data: {
          title,
          linkPaginate: `/${this.routeModule}/${path}`,
          linkAdd: ``,
          linkUpdate: ``,
          permission: [EP.Get, EP.Update],
          layer: [...this.layer, '| Edit'],
        },
      }
    );

    return this;
  }

  build(): Routes {
    return this.routes;
  }
}
